const content = $json.candidates?.[0]?.content?.parts
  ?.map((part) => part.text || '')
  .join('')
  .trim();

if (!content) {
  throw new Error('Gemini response did not contain candidates[0].content.parts[].text');
}

let normalizedContent = content;

// Defensive cleanup in case the model still wraps JSON in markdown fences.
if (normalizedContent.startsWith('```')) {
  normalizedContent = normalizedContent
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

// Validate that Backend receives a JSON string, not a loose object or markdown.
try {
  JSON.parse(normalizedContent);
} catch (error) {
  throw new Error(`Gemini returned malformed JSON: ${error.message}`);
}

const ctx = $('Build Per Push Prompt').item.json;
const usage = $json.usageMetadata || {};

return [{
  aiReviewId: ctx.aiReviewId,
  callbackUrl: ctx.callbackUrl,
  status: 'success',
  rawResponse: normalizedContent,
  modelName: $env.GEMINI_MODEL || 'gemini-2.5-flash',
  provider: 'google-gemini',
  tokenUsage: {
    inputTokens: usage.promptTokenCount || null,
    outputTokens: usage.candidatesTokenCount || null,
    totalTokens: usage.totalTokenCount || null
  }
}];

const ctx = $('Normalize Per Push').item.json;
const message = $json.error?.message || $json.message || $json.body?.message || 'Unknown workflow error';
return [{
  callbackUrl: ctx.callbackUrl,
  status: 'error',
  errorMessage: message
}];

const commits = Array.isArray($input.first().json) ? $input.first().json : [];
const ctx = $('Normalize Aggregate').item.json;
const compactCommits = commits.slice(0, 20).map((commit, index) => {
  const sha = commit.sha || '';
  const message = commit.commit?.message || '';
  const author = commit.commit?.author?.name || 'unknown';
  const date = commit.commit?.author?.date || '';
  return `${index + 1}. SHA: ${sha}
AUTHOR: ${author}
DATE: ${date}
MESSAGE: ${message}`;
}).join('

');

const prompt = `Ban la mot ky su phan tich code ky thuat cho he thong hackathon. Hay tong hop tinh hinh ky thuat cua repository dua tren lich su commit gan day va tra ve DUY NHAT mot JSON hop le, khong them markdown, khong giai thich ben ngoai JSON.

Bat buoc tra ve dung cac truong sau:
- reviewKind: "TEAM_AGGREGATE_TECHNICAL_AUDIT"
- status: "DONE"
- isScoreBased: false
- isFinalDecision: false
- overallPicture: { pushSummary, significantChange, changeImpactLevel, mainAffectedAreas }
- techStackDetected: { frontend, backend, database, ai, retrieval, testing }
- technicalFindings: array cac object { type, severity, title, evidence, comment, recommendedAction }
- rubricAwareComments: array
- suggestedTestCases: array { title, purpose, expectedObservation }
- suggestedJudgeQuestions: array string
- costControlNotes: { llmCallReason, skippedFiles, tokenSavingStrategy }
- historicalSynthesis: string
- currentTechnicalSnapshot: string
- riskSummary: array { severity, title, summary }
- judgeDashboardSummary: { headline, needsHumanReview, primaryConcerns, recommendedJudgeFocus }
- needsHumanReview: boolean

Gia tri hop le:
- changeImpactLevel: LOW, MEDIUM, HIGH, CRITICAL, UNKNOWN
- severity: LOW, MEDIUM, HIGH, CRITICAL
- technicalFindings.type: ARCHITECTURE, SECURITY, RELIABILITY, PERFORMANCE, TESTING, AI_USAGE, RAG, AGENT, DEPENDENCY, MAINTAINABILITY

Thong tin ngu canh:
- Repository: ${ctx.repositoryFullName}
- Default branch: ${ctx.defaultBranch}
- Batch ID: ${ctx.batchId || 'N/A'}
- So commit lay mau: ${commits.length}

Lich su commit gan day:
${compactCommits || '[Khong lay duoc lich su commit]'}

Neu khong du bang chung, van phai tra ve JSON hop le va dung gia tri trong tap cho phep. Khong duoc dua ra diem so hay ket luan chung cuoc.`;

return [{
  prompt,
  aiReviewId: ctx.aiReviewId,
  callbackUrl: ctx.callbackUrl,
  reviewKind: ctx.reviewKind
}];

